// Auto-generated land/ocean bitmask, 256x128 equirectangular, packed 1 bit/px.
// Derived from a public earth-topology texture, downsampled and thresholded, then
// base64 encoded so the dotted globe ships its continents inline (no runtime fetch).
// x: 0..W maps to longitude -180..+180; y: 0..H maps to latitude +90..-90.

export const MASK_W = 256;
export const MASK_H = 128;

const MASK_B64 =
  "";

let bits: Uint8Array | null = null;
function unpack(): Uint8Array {
  if (bits) return bits;
  const bin =
    typeof atob === "function"
      ? atob(MASK_B64)
      : Buffer.from(MASK_B64, "base64").toString("binary");
  const arr = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
  bits = arr;
  return arr;
}

/** True where the given latitude/longitude (degrees) falls on land. */
export function isLand(lat: number, lon: number): boolean {
  const b = unpack();
  let x = Math.floor(((lon + 180) / 360) * MASK_W);
  let y = Math.floor(((90 - lat) / 180) * MASK_H);
  if (x < 0) x = 0;
  else if (x >= MASK_W) x = MASK_W - 1;
  if (y < 0) y = 0;
  else if (y >= MASK_H) y = MASK_H - 1;
  const idx = y * MASK_W + x;
  return ((b[idx >> 3] >> (idx & 7)) & 1) === 1;
}
